{"id": "v19/support/word_blend", "version": 1, "symbol": "word_blend", "kind": "constructor", "status": "Accepted", "signature": "TERM word_blend(base: STRING / TERM, replacement: STRING / TERM, result_name?: STRING) -> TERM", "definition": "Constructs a morphological blend or portmanteau from base and replacement terms. descriptive lexical structure.", "aliases": ["portmanteau"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/example_of", "version": 1, "symbol": "example_of", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM example_of(example: TERM, concept: TERM)", "definition": "Asserts that an instance or term exemplifies a general concept, pattern, or category. example and concept are descriptive terms.", "aliases": ["exemplifies", "instance_of"], "shared_rules": ["v19/rule/trace-relations-general"]}
{"id": "v19/support/considered", "version": 1, "symbol": "considered", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM considered(subject: TERM)", "definition": "Asserts that an agent or speaker evaluated or entertained a specific candidate term or concept. subject is the evaluated term.", "aliases": ["evaluated", "weighed"], "dependencies": ["v19/support/subject"], "shared_rules": ["v19/rule/trace-relations-general"]}
{"id": "v19/support/attribute_claim", "version": 4, "symbol": "attribute_claim", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM attribute_claim(subject: STRING / TERM / ATOM[platform_label], property: STRING, value: STRING / NUMBER / BOOL / TERM / ATOM[platform_label])", "definition": "Asserts that a subject possesses a named property evaluated to a specific primitive or structured value. general property attribution claim.", "aliases": ["property_value", "word_property", "has_property", "property attribution"], "dependencies": ["v19/support/subject", "v19/lexical-group/platform_label"], "shared_rules": ["v19/rule/trace-relations-general"], "related": ["v19/support/requirement", "v19/support/has_attribute"]}
{"id": "v19/support/focus_of", "version": 1, "symbol": "focus_of", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM focus_of(subject: TERM, concept: STRING)", "definition": "Asserts that a subject term emphasizes or focuses on a given thematic concept. subject is a descriptive term.", "aliases": ["centered_on"], "dependencies": ["v19/support/subject"], "shared_rules": ["v19/rule/trace-relations-general"]}
{"id": "v19/support/has_style", "version": 1, "symbol": "has_style", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM has_style(target: CLAIM / EVENT / TERM, value: TERM / STRING)", "definition": "Asserts that an artifact, utterance, or action possesses a designated style. style qualifier.", "aliases": ["style_is"], "shared_rules": ["v19/rule/trace-relations-general"]}
{"id": "v19/support/request", "version": 1, "symbol": "request", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM request(target: TERM / STRING)", "definition": "Represents an active communicative request or constraint state in conversation tracking. target is the requested action or topic.", "aliases": ["user_request"], "shared_rules": ["v19/rule/trace-relations-general"]}
--
{"id": "v19/support/footnote", "version": 1, "symbol": "footnote", "kind": "constructor", "status": "Accepted", "signature": "TERM footnote(function: STRING, number: NUMBER) -> TERM", "definition": "Constructs a footnote reference or citation marker descriptor. document formatting descriptor.", "aliases": ["citation_note"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/pull_request", "version": 2, "symbol": "pull_request", "kind": "constructor", "status": "Accepted", "signature": "TERM pull_request(project: STRING / ATOM[platform_label], number: NUMBER) -> TERM", "definition": "Constructs a repository pull request reference. software repository reference.", "aliases": ["pr"], "dependencies": ["v19/lexical-group/platform_label"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/issue", "version": 2, "symbol": "issue", "kind": "constructor", "status": "Accepted", "signature": "TERM issue(project: STRING / ATOM[platform_label], number: NUMBER) -> TERM", "definition": "Constructs an issue tracker ticket reference. issue tracker descriptor.", "aliases": ["issue_ticket", "bug_report"], "dependencies": ["v19/lexical-group/platform_label"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/statement", "version": 3, "symbol": "statement", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM statement(fact: TERM)", "definition": "Foundational claim relation converting any descriptive TERM into an attributed, truth-evaluated assertion. universal fact assertion.", "aliases": ["assert_fact", "fact_claim", "claim_statement"], "shared_rules": ["v19/rule/trace-relations-general"], "related": ["v19/support/attribute_claim", "v19/support/has_state", "v19/support/spatial_state"]}
{"id": "v19/recipient-value/role_sister", "version": 1, "symbol": "role_sister", "kind": "value", "status": "Accepted", "category": "recipient-value", "definition": "Sister participant role in family/event context.", "aliases": ["sister"], "shared_rules": ["v19/rule/category/recipient-value"]}
{"id": "v19/recipient-value/role_kids", "version": 1, "symbol": "role_kids", "kind": "value", "status": "Accepted", "category": "recipient-value", "definition": "Children/kids participant group in event context.", "aliases": ["kids", "children"], "shared_rules": ["v19/rule/category/recipient-value"]}
{"id": "v19/cuisine-value/cuisine_mediterranean", "version": 1, "symbol": "cuisine_mediterranean", "kind": "value", "status": "Accepted", "category": "cuisine-value", "definition": "Mediterranean culinary cuisine style.", "aliases": ["mediterranean"], "shared_rules": ["v19/rule/category/cuisine-value"]}
--
{"id": "v19/support/reconcile_code", "version": 1, "symbol": "reconcile_code", "kind": "constructor", "status": "Accepted", "signature": "TERM reconcile_code(entities: LIST[TERM], objective: STRING / TERM) -> TERM", "definition": "Constructs a specification to reconcile multiple code entities or implementations to standardize their behavior.", "not": "a general file merge operation", "aliases": ["reconcile_functions", "standardize_behavior", "reconcile_implementations"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/unit-value/unit_kilometer", "version": 1, "symbol": "unit_kilometer", "kind": "value", "status": "Accepted", "category": "unit-value", "definition": "Standard metric measurement unit of distance equal to 1,000 meters.", "not": "temporal duration units (like unit_minute) or non-metric distance units", "aliases": ["km", "kilometer", "kilometres", "kilometers"]}
{"id": "v19/unit-value/unit_liter", "version": 1, "symbol": "unit_liter", "kind": "value", "status": "Accepted", "category": "unit-value", "definition": "Standard metric measurement unit of liquid volume equal to 1 cubic decimeter (1,000 milliliters).", "not": "digital capacity units (like cap_gb) or temporal duration units", "aliases": ["l", "liter", "liters", "litres"]}
{"id": "v19/support/rate", "version": 1, "symbol": "rate", "kind": "constructor", "status": "Accepted", "signature": "TERM rate(denominator: TERM, numerator: TERM) -> TERM", "definition": "Constructs a structured proportional rate or frequency relating a numerator measured quantity to a denominator reference quantity.", "not": "an asserted factual attribution (use attribute_claim) or bound constraint (use requirement)", "aliases": ["per_unit", "ratio"], "shared_rules": ["v19/rule/support-primitives-general"]}
